package com.asmj.marketplace.service.controller;
import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.service.controller.ServiceDtos.*;import com.asmj.marketplace.service.service.ServiceMarketplaceService;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/services") @RequiredArgsConstructor public class ServiceController{final ServiceMarketplaceService s;String e(Authentication a){return a.getName();}@GetMapping public ApiResponse<?> all(){return ApiResponse.ok("",s.publicServices());}@PreAuthorize("hasRole('VENDOR')") @GetMapping("/vendor") public ApiResponse<?> vendor(Authentication a){return ApiResponse.ok("",s.vendorServices(e(a)));}@PreAuthorize("hasRole('VENDOR')") @PostMapping("/vendor") public ApiResponse<?> create(Authentication a,@RequestBody ServiceRequest r){return ApiResponse.ok("",s.save(e(a),r,null));}@PreAuthorize("hasRole('VENDOR')") @PutMapping("/vendor/{id}") public ApiResponse<?> edit(Authentication a,@PathVariable String id,@RequestBody ServiceRequest r){return ApiResponse.ok("",s.save(e(a),r,id));}@PreAuthorize("hasRole('VENDOR')") @GetMapping("/vendor/schedules") public ApiResponse<?> schedules(Authentication a){return ApiResponse.ok("",s.schedules(e(a)));}@PreAuthorize("hasRole('VENDOR')") @PostMapping("/vendor/schedules") public ApiResponse<?> schedule(Authentication a,@RequestBody ScheduleRequest r){return ApiResponse.ok("",s.saveSchedule(e(a),r,null));}@PreAuthorize("hasAnyRole('USER','VENDOR','ADMIN')") @PostMapping("/bookings") public ApiResponse<?> book(Authentication a,@RequestBody BookingRequest r){return ApiResponse.ok("",s.create(e(a),r));}@PreAuthorize("isAuthenticated()") @GetMapping("/bookings/my") public ApiResponse<?> my(Authentication a){return ApiResponse.ok("",s.my(e(a)));}@PreAuthorize("hasAnyRole('VENDOR','ADMIN')") @GetMapping("/bookings/vendor") public ApiResponse<?> vb(Authentication a){return ApiResponse.ok("",s.vendorBookings(e(a)));}@PreAuthorize("isAuthenticated()") @PutMapping("/bookings/{id}/status") public ApiResponse<?> status(Authentication a,@PathVariable String id,@RequestBody StatusRequest r){return ApiResponse.ok("",s.status(e(a),id,r));}@PreAuthorize("isAuthenticated()") @PostMapping("/bookings/{id}/reschedule") public ApiResponse<?> reschedule(Authentication a,@PathVariable String id,@RequestBody RescheduleRequest r){return ApiResponse.ok("",s.reschedule(e(a),id,r));}@PreAuthorize("hasRole('VENDOR')") @PostMapping("/bookings/{id}/complete") public ApiResponse<?> complete(Authentication a,@PathVariable String id,@RequestBody CompletionRequest r){return ApiResponse.ok("",s.complete(e(a),id,r));}}
